1	import { describe, it, expect } from "vitest";
2	import { execFileSync } from "node:child_process";
3	
4	const runCli = (scenario: unknown): string =>
5	  execFileSync("npx", ["tsx", "src/cli.ts"], {
6	    input: JSON.stringify(scenario),
7	    encoding: "utf8",
8	  });
