10	describe("claim-office CLI", () => {
11	  it("reads a scenario from stdin and writes { results } JSON to stdout", () => {
12	    const stdout = runCli({
13	      customer: { yearsWithMHPCO: 5 },
14	      steps: [
15	        {
16	          op: "quote",
17	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
18	        },
19	        {
20	          op: "claim",
21	          policy: 0,
22	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
23	        },
24	      ],
25	    });
26	
27	    expect(JSON.parse(stdout)).toEqual({
28	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
29	    });
30	  });
31	
32	  it.todo("exits with a non-zero status code and writes an error to stderr on an invalid scenario");
33	});
