1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioResult = {
13	  results: StepResult[];
14	};
15	
16	const BASE_PREMIUMS = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	} as const satisfies Record<string, number>;
24	
25	const INSURANCE_VALUES = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	} as const satisfies Record<keyof typeof BASE_PREMIUMS, number>;
33	
34	type InsurableItemType = keyof typeof BASE_PREMIUMS;
35	
36	type Item = {
37	  type: InsurableItemType;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type QuoteStep = {
44	  op: "quote";
45	  items: Item[];
46	};
47	
48	type Damage = {
49	  itemType: string;
50	  amount: number;
51	};
52	
53	type Incident = {
54	  cause: string;
55	  damages: Damage[];
56	};
57	
58	type ClaimStep = {
59	  op: "claim";
60	  policy: number;
61	  incident: Incident;
62	};
63	
64	type Step = QuoteStep | ClaimStep;
65	
66	type Customer = {
67	  yearsWithMHPCO: number;
68	};
69	
70	type Scenario = {
71	  customer: Customer;
72	  steps: Step[];
73	};
74	
75	const PROCESSING_FEE = 5;
76	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
80	const LOYALTY_THRESHOLD_YEARS = 2;
81	const LOYALTY_DISCOUNT_PERCENT = 20;
82	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
83	
84	const percentOf = (amount: number, percent: number): number =>
85	  (amount * percent) / 100;
86	
87	// The MHPCO always rounds in its own favour: premiums (which the customer
88	// pays) round up, payouts (which it pays out) round down.
89	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
90	
91	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
92	
93	// Exactly this many components of the same type form a "building block",
94	// priced as a unit rather than per item.
95	const BUILDING_BLOCK_SIZE = 3;
96	const BUILDING_BLOCK_BASE_PREMIUM = 60;
97	
98	const sumOf = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// The MHPCO refuses to process a scenario it cannot price or pay out on. Every
102	// such refusal names the offending value, so they all take the same shape:
103	// yield the value when there is one, reject with an explanation when there
104	// is not.
105	const orRejected = <Value>(
106	  value: Value | undefined,
107	  reason: string,
108	): Value => {
109	  if (value === undefined) {
110	    throw new Error(reason);
111	  }
112	
113	  return value;
114	};
115	
116	// A requirement the MHPCO places on the scenario it is handed, paired with the
117	// explanation it gives when the requirement is not met. Checking one yields the
118	// subject back, so requirements compose with the rest of the pipeline the same
119	// way `orRejected` does.
120	type Requirement<Subject> = {
121	  isMetBy: (subject: Subject) => boolean;
122	  reasonRejecting: (subject: Subject) => string;
123	};
124	
125	const meeting = <Subject>(
126	  requirement: Requirement<Subject>,
127	  subject: Subject,
128	): Subject =>
129	  orRejected(
130	    requirement.isMetBy(subject) ? subject : undefined,
131	    requirement.reasonRejecting(subject),
132	  );
133	
134	// The MHPCO insures exactly the item types its price list names.
135	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
136	
137	const isInsurableItemType = (type: string): type is InsurableItemType =>
138	  insurableItemTypes.includes(type as InsurableItemType);
139	
140	const alikeItemGroups = (items: Item[]): Item[][] =>
141	  insurableItemTypes
142	    .map((type) => items.filter((item) => item.type === type))
143	    .filter((alikeItems) => alikeItems.length > 0);
144	
145	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
146	  alikeItems.length === BUILDING_BLOCK_SIZE;
147	
148	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
149	  formsBuildingBlock(alikeItems)
150	    ? BUILDING_BLOCK_BASE_PREMIUM
151	    : sumOf(alikeItems.map(itemBasePremiumOf));
152	
153	const policyBasePremiumOf = (items: Item[]): number =>
154	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
155	
156	const isCursed = (item: Item): boolean => item.cursed === true;
157	
158	// An item without an enchantment counts as enchantment 0 everywhere.
159	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
160	
161	const isHighlyEnchanted = (item: Item): boolean =>
162	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
163	
164	// A modifier adjusts a base premium by a percentage of it, when it applies to
165	// the subject it is about (an item, a contract, ...). A surcharge has a
166	// positive percent, a discount a negative one, so they all combine by summing.
167	// Modifiers are cumulative: every applicable one applies.
168	type Modifier<Subject> = {
169	  appliesTo: (subject: Subject) => boolean;
170	  percent: number;
171	};
172	
173	const modifierTotalOf = <Subject>(
174	  modifiers: Modifier<Subject>[],
175	  subject: Subject,
176	  basePremium: number,
177	): number =>
178	  sumOf(
179	    modifiers
180	      .filter((modifier) => modifier.appliesTo(subject))
181	      .map((modifier) => percentOf(basePremium, modifier.percent)),
182	  );
183	
184	const ITEM_MODIFIERS: Modifier<Item>[] = [
185	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
186	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
187	];
188	
189	// Item-specific modifiers apply to the base premium of the affected item.
190	const itemModifierTotalOf = (item: Item): number =>
191	  modifierTotalOf(ITEM_MODIFIERS, item, itemBasePremiumOf(item));
192	
193	const isLongStanding = (customer: Customer): boolean =>
194	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
195	
196	// A contract is one quote within a scenario. A quote is a follow-up when the
197	// customer already holds a policy with the MHPCO at the time it is drawn up.
198	type Contract = {
199	  customer: Customer;
200	  heldPoliciesBefore: number;
201	};
202	
203	const isFollowUpContract = (contract: Contract): boolean =>
204	  contract.heldPoliciesBefore > 0;
205	
206	// Policy-wide modifiers apply to the policy base premium and are about the
207	// contract as a whole rather than any single item.
208	const alwaysApplies = (): boolean => true;
209	
210	const POLICY_MODIFIERS: Modifier<Contract>[] = [
211	  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
212	  {
213	    appliesTo: (contract) => isLongStanding(contract.customer),
214	    percent: -LOYALTY_DISCOUNT_PERCENT,
215	  },
216	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
217	];
218	
219	const policyModifierTotalOf = (
220	  contract: Contract,
221	  policyBasePremium: number,
222	): number => modifierTotalOf(POLICY_MODIFIERS, contract, policyBasePremium);
223	
224	const quote = (step: QuoteStep, contract: Contract): QuoteResult => {
225	  const policyBasePremium = policyBasePremiumOf(step.items);
226	  const itemModifiers = sumOf(step.items.map(itemModifierTotalOf));
227	  const policyModifiers = policyModifierTotalOf(contract, policyBasePremium);
228	
229	  return {
230	    premium: roundedUpInMHPCOsFavour(
231	      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
232	    ),
233	  };
234	};
235	
236	const DEDUCTIBLE_PER_DAMAGE = 100;
237	const CAP_MULTIPLIER = 2;
238	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
239	const PARTIAL_REIMBURSEMENT_PERCENT = 50;
240	
241	const roundedDownInMHPCOsFavour = (payout: number): number =>
242	  Math.floor(payout);
243	
244	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];
245	
246	// A policy is created by a quote step and remembers how much of its cap the
247	// customer has already claimed.
248	type Policy = {
249	  items: Item[];
250	  remainingCap: number;
251	};
252	
253	const isReimbursedInPart = (item: Item): boolean =>
254	  enchantmentOf(item) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
255	
256	// The reimbursement clauses decide how much of the damage is covered; the
257	// deductible is then withheld from that amount.
258	const reimbursementOf = (damage: Damage, item: Item): number =>
259	  isReimbursedInPart(item)
260	    ? percentOf(damage.amount, PARTIAL_REIMBURSEMENT_PERCENT)
261	    : damage.amount;
262	
263	// The MHPCO does not entertain damages that would pay it.
264	const IS_NOT_NEGATIVE: Requirement<Damage> = {
265	  isMetBy: (damage) => damage.amount >= 0,
266	  reasonRejecting: (damage) =>
267	    `damage amount cannot be negative: ${damage.amount}`,
268	};
269	
270	const damagePayoutOf = (damage: Damage, item: Item): number =>
271	  reimbursementOf(meeting(IS_NOT_NEGATIVE, damage), item) -
272	  DEDUCTIBLE_PER_DAMAGE;
273	
274	// What a damage entry resolved to: the entry itself and the insured item it is
275	// charged against.
276	type ChargedDamage = {
277	  damage: Damage;
278	  item: Item;
279	};
280	
281	// Each damage entry is about one insured item, and no two entries may be about
282	// the same one: a policy covering a single sword cannot suffer two damaged
283	// swords. Entries are charged against the items still unaccounted for, each
284	// claimed item dropping out of reach of the entries that follow, so the MHPCO
285	// refuses both damages to what it did not insure and damages beyond the number
286	// of alike items it did.
287	const chargedDamagesIn = (
288	  policy: Policy,
289	  incident: Incident,
290	): ChargedDamage[] => {
291	  let unclaimed = policy.items;
292	
293	  return incident.damages.map((damage) => {
294	    // Two slots of a policy may hold the very same item object (a customer
295	    // insuring two identical swords), so a claimed slot is dropped by its
296	    // position, never by identity.
297	    const claimedSlot = unclaimed.findIndex(
298	      (candidate) => candidate.type === damage.itemType,
299	    );
300	    const item = orRejected(
301	      unclaimed[claimedSlot],
302	      `damaged item is not insured by this policy: ${damage.itemType}`,
303	    );
304	    unclaimed = [
305	      ...unclaimed.slice(0, claimedSlot),
306	      ...unclaimed.slice(claimedSlot + 1),
307	    ];
308	
309	    return { damage, item };
310	  });
311	};
312	
313	const chargedDamagePayoutOf = ({ damage, item }: ChargedDamage): number =>
314	  damagePayoutOf(damage, item);
315	
316	const incidentPayoutOf = (incident: Incident, policy: Policy): number =>
317	  roundedDownInMHPCOsFavour(
318	    sumOf(chargedDamagesIn(policy, incident).map(chargedDamagePayoutOf)),
319	  );
320	
321	// The total payout per policy is capped, so a claim can only draw what the cap
322	// still holds.
323	const drawnFromCap = (desiredPayout: number, policy: Policy): number =>
324	  Math.min(desiredPayout, policy.remainingCap);
325	
326	// Claiming draws the payout from the policy's remaining cap, so it yields both
327	// the result and the policy as it stands afterwards, rather than mutating.
328	const claim = (
329	  step: ClaimStep,
330	  policy: Policy,
331	): { result: ClaimResult; policy: Policy } => {
332	  const payout = drawnFromCap(incidentPayoutOf(step.incident, policy), policy);
333	  const remainingCap = policy.remainingCap - payout;
334	
335	  return {
336	    result: { payout, remainingCap },
337	    policy: { ...policy, remainingCap },
338	  };
339	};
340	
341	const policyFor = (items: Item[]): Policy => ({
342	  items,
343	  remainingCap: CAP_MULTIPLIER * sumOf(items.map(insuranceValueOf)),
344	});
345	
346	// A scenario is processed step by step: each step produces a result and may
347	// leave behind policies the later steps claim against. Policies are keyed by
348	// the index of the quote step that created them, which is how claim steps
349	// refer to them.
350	type Office = {
351	  policies: Map<number, Policy>;
352	  results: StepResult[];
353	};
354	
355	const emptyOffice = (): Office => ({ policies: new Map(), results: [] });
356	
357	// The scenario arrives as untyped JSON, so the item types it names have to be
358	// checked against the MHPCO's price list before anything is priced.
359	const IS_INSURABLE: Requirement<Item> = {
360	  isMetBy: (item) => isInsurableItemType(item.type),
361	  reasonRejecting: (item) => `unknown item type: ${item.type}`,
362	};
363	
364	// Every step yields its result plus the policy it wrote, under the key that
365	// later steps use to find it.
366	type StepOutcome = {
367	  result: StepResult;
368	  policyKey: number;
369	  policy: Policy;
370	};
371	
372	const withOutcomeRecorded = (office: Office, outcome: StepOutcome): Office => ({
373	  policies: new Map(office.policies).set(outcome.policyKey, outcome.policy),
374	  results: [...office.results, outcome.result],
375	});
376	
377	const outcomeOf = (
378	  office: Office,
379	  step: Step,
380	  stepIndex: number,
381	  customer: Customer,
382	): StepOutcome => {
383	  if (step.op === "quote") {
384	    const items = step.items.map((item) => meeting(IS_INSURABLE, item));
385	    // Claims re-file the policy they draw on under its existing key, so the
386	    // number of policies on file only ever grows on a quote.
387	    const contract = { customer, heldPoliciesBefore: office.policies.size };
388	
389	    return {
390	      result: quote(step, contract),
391	      policyKey: stepIndex,
392	      policy: policyFor(items),
393	    };
394	  }
395	
396	  const claimed = claim(step, office.policies.get(step.policy)!);
397	
398	  return {
399	    result: claimed.result,
400	    policyKey: step.policy,
401	    policy: claimed.policy,
402	  };
403	};
404	
405	export const runScenario = (scenario: Scenario): ScenarioResult => {
406	  const office = scenario.steps.reduce(
407	    (office, step, stepIndex) =>
408	      withOutcomeRecorded(
409	        office,
410	        outcomeOf(office, step, stepIndex, scenario.customer),
411	      ),
412	    emptyOffice(),
413	  );
414	
415	  return { results: office.results };
416	};
